package com.personal.assistant.module.ai.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.ai.dto.*;import com.personal.assistant.module.ai.entity.AiInvocation;import com.personal.assistant.module.ai.service.AiGatewayService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/ai")public class AiController{private final AiGatewayService service;public AiController(AiGatewayService service){this.service=service;}private Long uid(){return SecurityContextHelper.currentUserId();}@GetMapping("/configs")public ApiResponse<List<Map<String,Object>>>configs(){return ApiResponse.success(service.configs(uid()));}@PostMapping("/configs")public ApiResponse<Long>save(@Valid @RequestBody AiConfigRequest r){return ApiResponse.success(service.saveConfig(uid(),r));}@PostMapping("/assist")public ApiResponse<AiInvocation>assist(@Valid @RequestBody AiAssistRequest r){return ApiResponse.success(service.assist(uid(),r));}@GetMapping("/invocations")public ApiResponse<List<AiInvocation>>logs(){return ApiResponse.success(service.logs(uid()));}@PostMapping("/invocations/{id}/confirm")public ApiResponse<Void>confirm(@PathVariable Long id){service.confirm(uid(),id);return ApiResponse.success();}}
